mapper.delete:
delete from TRD_BANK_MANUAL_SETTLE_INFO
where SETTLE_DATE = #{batchDate,jdbcType=DATE}
AND CREATE_USER = #{createrUser}

mapper.select:
SELECT
    P.ACCT_NO CASHACCTID
FROM PTL_CAPACCT_INFO P
LEFT JOIN STL_CAPACCT_INFO S ON P.ACCT_NO = S.ACCT_NO
where P.PORTFOLIO_ID = #{portfolioId}
AND P.ACCT_TYPE = #{acctType}
AND P.CCY =#{ccy}
and rownum=1
